// ======================================================
// SD CARD DRIVER DEPENDENCY
//
// This file uses the FatFS API (f_mount, f_open, f_read, f_close, etc.).
// FatFS is the standard embedded FAT filesystem library by ChaN:
//   http://elm-chan.org/fsw/ff/
//
// FatFS SD SPI driver — carlk3/no-OS-FatFS-SD-SPI-RPi-Pico
// Added to the build via FetchContent in CMakeLists.txt.
// Hardware pin configuration is in board/hw_config.c.
#include "ff.h"       // FatFS core (f_open, f_read, f_close, etc.)
#include "sd_card.h"  // SPI SD card driver (sd_init_driver, etc.)
//
// Until the driver is added, all functions compile but return false/0.
// ======================================================

// ======================================================
// CARD DETECT
//
// PIN_SD_CARD_DETECT should be defined in board_config.h once the
// schematic is updated. The signal is active-LOW (card inserted = LOW)
// with a 10kΩ pull-up to 3.3V on the PCB.
//
// If PIN_SD_CARD_DETECT is not defined, card_is_present() falls back
// to an optimistic assumption (always true) so the driver still attempts
// an SPI probe — slow but functional without the hardware pin.
// ======================================================

static bool card_is_present()
{
#ifdef PIN_SD_CARD_DETECT
    // Active-low: LOW = card inserted, HIGH = absent.
    return gpio_get(PIN_SD_CARD_DETECT) == 0;
#else
    // No hardware detect pin — optimistically attempt access.
    // If the SD init fails, callers treat that as "no card".
    return true;
#endif
}


// ======================================================
// WAV FILE PARSER
//
// Supports 16-bit and 24-bit mono or stereo PCM .wav files.
// Only reads the RIFF/fmt/data chunks; ignores LIST, INFO, etc.
// Stereo files are read as mono by taking the left channel only.
//
// All WAV field values are little-endian (matches RP2040 native byte order).
// ======================================================

#pragma pack(push, 1)
struct WavRiffHeader {
    char     riff_id[4];    // "RIFF"
    uint32_t file_size;     // Total file size minus 8 bytes
    char     wave_id[4];    // "WAVE"
};

struct WavFmtChunk {
    char     chunk_id[4];   // "fmt "
    uint32_t chunk_size;    // Should be 16 for PCM
    uint16_t audio_format;  // 1 = PCM (uncompressed)
    uint16_t num_channels;  // 1 = mono, 2 = stereo
    uint32_t sample_rate;   // e.g. 44100
    uint32_t byte_rate;     // sample_rate * num_channels * bits_per_sample / 8
    uint16_t block_align;   // num_channels * bits_per_sample / 8
    uint16_t bits_per_sample; // 16 or 24
};

struct WavDataChunkHeader {
    char     chunk_id[4];   // "data"
    uint32_t chunk_size;    // Number of bytes of audio data
};
#pragma pack(pop)

// Parsed metadata returned by wav_read_header().
struct WavInfo {
    uint16_t num_channels;
    uint32_t sample_rate;
    uint16_t bits_per_sample;
    uint32_t data_offset;   // Byte offset of first audio sample in file
    uint32_t data_bytes;    // Total bytes of audio data
    uint32_t num_samples;   // Total sample frames (per channel)
};

