// ======================================================
// SAMPLE STORAGE — SRAM POOL FOR SD-CARD-LOADED SAMPLES
//
// Samples loaded from the SD card are copied into this SRAM pool at
// startup so the core 1 render loop can access them without SD card
// latency. Each sample is stored as sign-extended 24-bit int32_t values.
//
// MEMORY BUDGET (RP2040 total SRAM = 264 KB):
//   Firmware + stack + DMA buffers: ~100 KB
//   Available for sample data:      ~128 KB
//   SAMPLE_POOL_INT32 = 32768 × 4 = 128 KB
//   At 44100 Hz mono: ~0.74 seconds total across ALL slots combined.
//
// This is intentionally small. It suits short percussive samples (drums,
// stabs). For longer samples use SD card streaming (future work).
//
// Flash-embedded assets do NOT use this pool — they live in flash and
// the synth engine accesses them directly via XIP pointers. Only their
// parsed int32_t header info is stored here.
// ======================================================

static constexpr uint32_t SAMPLE_POOL_INT32 = 32768; // 128 KB SRAM budget

static int32_t sample_pool[SAMPLE_POOL_INT32];
static uint32_t sample_pool_used = 0;

// Per-slot metadata: where in sample_pool the data starts and how long it is.
struct LoadedSample {
    bool     loaded;
    int32_t* data;         // Pointer into sample_pool
    uint32_t num_frames;   // Number of playable sample frames
    uint32_t sample_rate;  // Original sample rate (may differ from AUDIO_SAMPLE_RATE_HZ)
};

static LoadedSample loaded_samples[MAX_VOICES][MAX_SAMPLES_PER_VOICE];

static void loaded_samples_clear()
{
    memset(loaded_samples, 0, sizeof(loaded_samples));
    sample_pool_used = 0;
}


// ======================================================
// INTERNAL HELPERS
// ======================================================

// Allocate 'num_frames' int32_t slots from the pool.
// Returns nullptr if the pool is exhausted.
static int32_t* pool_alloc(uint32_t num_frames)
{
    if (sample_pool_used + num_frames > SAMPLE_POOL_INT32) {
        printf("SAMPLE_LOADER: pool exhausted (need %lu, have %lu)\n",
               (unsigned long)num_frames,
               (unsigned long)(SAMPLE_POOL_INT32 - sample_pool_used));
        return nullptr;
    }

    int32_t* ptr = &sample_pool[sample_pool_used];
    sample_pool_used += num_frames;
    return ptr;
}

