bool sample_loader_init(const char* voice_config_path)
{
    printf("SAMPLE_LOADER: init...\n");

    if (!card_is_present()) {
        printf("SAMPLE_LOADER: no SD card detected. Using built-in default voices.\n");
        return false;
    }

    // TODO: mount filesystem once here (not per-operation):
    // dotstar_spi_acquire();
    // FATFS fs;
    // FRESULT res = f_mount(&fs, "", 1);
    // dotstar_spi_release();
    // if (res != FR_OK) {
    //     printf("SAMPLE_LOADER: SD card mount failed (err %d).\n", res);
    //     return false;
    // }
    // printf("SAMPLE_LOADER: SD card mounted.\n");

    bool config_ok = sample_loader_load_voice_config(voice_config_path);

    if (config_ok) {
        uint32_t loaded = sample_loader_preload_samples();
        printf("SAMPLE_LOADER: init complete. %lu sample slots preloaded.\n",
               (unsigned long)loaded);
    } else {
        printf("SAMPLE_LOADER: no voice config found — using built-in defaults.\n");
    }

    return true;  // Partial success: even without config, card was detected.
}

const int32_t* sample_loader_get_sample(
    uint8_t   voice_index,
    uint8_t   note_index,
    uint32_t* out_num_frames,
    uint32_t* out_sample_rate
) {
    if (voice_index >= MAX_VOICES || note_index >= MAX_SAMPLES_PER_VOICE) {
        return nullptr;
    }

    const LoadedSample& slot = loaded_samples[voice_index][note_index];

    if (!slot.loaded || slot.data == nullptr || slot.num_frames == 0) {
        return nullptr;
    }

    if (out_num_frames)   *out_num_frames   = slot.num_frames;
    if (out_sample_rate)  *out_sample_rate  = slot.sample_rate;

    return slot.data;
}

