uint32_t sample_loader_preload_samples()
{
    if (!card_is_present()) {
        printf("SAMPLE_LOADER: no SD card detected, skipping sample preload.\n");
        return 0;
    }

    printf("SAMPLE_LOADER: preloading samples...\n");

    loaded_samples_clear();

    uint32_t loaded_count = 0;

    for (uint8_t v = 0; v < MAX_VOICES; v++) {
        const VoiceDefinition* voice = voice_definitions_get(v);

        if (voice == nullptr || voice->type != VOICE_TYPE_PLAYBACK) {
            continue;
        }

        for (uint8_t s = 0; s < MAX_SAMPLES_PER_VOICE; s++) {
            const SampleSlot& slot = voice->samples[s];

            if (!slot.assigned || slot.filename[0] == '\0') {
                continue;
            }

            int32_t*  data   = nullptr;
            uint32_t  frames = 0;
            uint32_t  rate   = 0;

            if (load_wav_file(slot.filename, &data, &frames, &rate)) {
                loaded_samples[v][s].loaded      = true;
                loaded_samples[v][s].data        = data;
                loaded_samples[v][s].num_frames  = frames;
                loaded_samples[v][s].sample_rate = rate;

                printf("SAMPLE_LOADER: voice %u slot %u loaded %lu frames from %s\n",
                       v, s, (unsigned long)frames, slot.filename);
                loaded_count++;
            } else {
                printf("SAMPLE_LOADER: voice %u slot %u FAILED to load %s\n",
                       v, s, slot.filename);
            }
        }
    }

    printf("SAMPLE_LOADER: preload complete — %lu sample slots loaded.\n",
           (unsigned long)loaded_count);

    return loaded_count;
}

